import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"GLM Coding Plan glossary","description":"What the plan is and is not: subscription vs chat vs metered API, credits, and the coding endpoint.","frontmatter":{"title":"GLM Coding Plan glossary","description":"What the plan is and is not: subscription vs chat vs metered API, credits, and the coding endpoint.","domain":"product","tags":["coding-plan"],"role":"glossary"},"headers":[],"relativePath":"products/glm-coding/glm-coding-glossary.md","filePath":"products/glm-coding/glm-coding-glossary.md","lastUpdated":1787110548000}'),n={name:"products/glm-coding/glm-coding-glossary.md"};function i(r,e,d,l,p,c){return o(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="glm-coding-plan-glossary" tabindex="-1">GLM Coding Plan glossary <a class="header-anchor" href="#glm-coding-plan-glossary" aria-label="Permalink to &quot;GLM Coding Plan glossary&quot;">​</a></h1><p>No steps. Split the colliding names, then the cheatsheet rows make sense. Which door to open: <a href="./">learning map</a>.</p><h2 id="how-the-pieces-sit" tabindex="-1">How the pieces sit <a class="header-anchor" href="#how-the-pieces-sit" aria-label="Permalink to &quot;How the pieces sit&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Z.ai / ChatGLM          chat products (#74)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>Standard Model API      /api/paas/v4, your own apps</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>GLM Coding Plan         subscription: GLM only inside listed tools</span></span>
<span class="line"><span>        ├── Coding agents (Claude Code, Cursor, …)</span></span>
<span class="line"><span>        ├── General-purpose agents (OpenClaw, …) best-effort</span></span>
<span class="line"><span>        └── Coding Tool Helper     loader, not an agent</span></span></code></pre></div><h2 id="glm-coding-plan" tabindex="-1">GLM Coding Plan <a class="header-anchor" href="#glm-coding-plan" aria-label="Permalink to &quot;GLM Coding Plan&quot;">​</a></h2><p><strong>What it is:</strong> “A subscription package designed specifically for AI-powered coding” (<a href="https://docs.z.ai/devpack/overview" target="_blank" rel="noreferrer">Overview</a>).</p><p><strong>Why it exists:</strong> Use GLM inside Claude Code / Cursor / other listed agents under a credit cap, instead of paying the general API per token.</p><p><strong>What it is not:</strong> Z.ai chat, ChatGLM, a first-party terminal agent, or a general-purpose API pack.</p><h2 id="supported-tools" tabindex="-1">Supported tools <a class="header-anchor" href="#supported-tools" aria-label="Permalink to &quot;Supported tools&quot;">​</a></h2><p><strong>What it is:</strong> The official Coding Agent and general-purpose lists on <a href="https://docs.z.ai/devpack/tool/others" target="_blank" rel="noreferrer">tool/others</a>. Off-list use does not get plan benefits.</p><p><strong>Why it exists:</strong> Coding agents are expensive. The vendor keeps plan capacity on named clients plus dedicated endpoints.</p><p><strong>What it is not:</strong> “Any client that accepts a Base URL.” The China and global lists differ. Do not copy one onto the other.</p><h2 id="coding-endpoint" tabindex="-1">Coding endpoint <a class="header-anchor" href="#coding-endpoint" aria-label="Permalink to &quot;Coding endpoint&quot;">​</a></h2><p><strong>What it is:</strong> Plan-only Anthropic / OpenAI URLs on <code>api.z.ai</code> (<code>/api/anthropic</code>, <code>/api/coding/paas/v4</code>, <code>/api/v1</code>).</p><p><strong>Why it exists:</strong> The same key aimed at <code>/api/paas/v4</code> is the general API. The Cursor page calls that out explicitly.</p><p><strong>What it is not:</strong> <code>open.bigmodel.cn</code>. That is the China twin. Keys and hosts stay in their region.</p><h2 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h2><p><strong>What it is:</strong> A 5-hour cap and a weekly cap. Models burn credits from tokens × multipliers / 10,000. MCP burns credits per call.</p><p><strong>Why it exists:</strong> One ledger across peak / off-peak, several models, and MCP.</p><p><strong>What it is not:</strong> Wallet cash. China Overview: when plan credits run out, wait for the next 5-hour window; other packs / balance are not drained.</p><h2 id="best-effort-agents" tabindex="-1">Best-effort agents <a class="header-anchor" href="#best-effort-agents" aria-label="Permalink to &quot;Best-effort agents&quot;">​</a></h2><p><strong>What it is:</strong> General-purpose tools (OpenClaw, Hermes Agent, SillyTavern on the global list). Official: served on a best-effort basis; high load may rate-limit. China Overview names this <strong>secondary scheduling</strong> and gives Coding Agent preemption.</p><p><strong>Why it exists:</strong> Most plan traffic is coding. Shared capacity prefers coding agents.</p><p><strong>What it is not:</strong> “OpenClaw is unsupported.” It is listed; it is not first-class.</p><h2 id="team-plan-key" tabindex="-1">Team Plan key <a class="header-anchor" href="#team-plan-key" aria-label="Permalink to &quot;Team Plan key&quot;">​</a></h2><p><strong>What it is:</strong> The credential Team members copy from Team Coding Plan &gt; My Plan. “Not interchangeable with other Z.AI&#39;s API Keys” (<a href="https://docs.z.ai/devpack/quick-start" target="_blank" rel="noreferrer">Quick Start</a>).</p><p><strong>Why it exists:</strong> Seats and org billing must not mix with a personal key.</p><p><strong>What it is not:</strong> The platform key the admin already had before buying seats.</p><h2 id="coding-tool-helper" tabindex="-1">Coding Tool Helper <a class="header-anchor" href="#coding-tool-helper" aria-label="Permalink to &quot;Coding Tool Helper&quot;">​</a></h2><p><strong>What it is:</strong> CLI <code>@z_ai/coding-helper</code> (<code>coding-helper</code> / <code>chelper</code>). Loads the plan into Claude Code, OpenCode, Crush, and Factory Droid.</p><p><strong>Why it exists:</strong> Avoid hand-editing <code>settings.json</code> and MCP.</p><p><strong>What it is not:</strong> A coding agent. It does not auto-wire Cursor.</p><h2 id="server-side-model-mapping" tabindex="-1">Server-side model mapping <a class="header-anchor" href="#server-side-model-mapping" aria-label="Permalink to &quot;Server-side model mapping&quot;">​</a></h2><p><strong>What it is:</strong> After Claude Code is pointed at the plan, the UI may still show Opus / Sonnet / Haiku while the server maps them to GLM (China Claude page; global page documents the env mapping).</p><p><strong>Why it exists:</strong> Keep the Claude Code UI. Hard-coded mappings go stale when the plan default model changes.</p><p><strong>What it is not:</strong> Anthropic inference. <code>/status</code> should show <code>glm-*</code>.</p><h2 id="global-site-vs-china-site" tabindex="-1">Global site vs China site <a class="header-anchor" href="#global-site-vs-china-site" aria-label="Permalink to &quot;Global site vs China site&quot;">​</a></h2><p><strong>What it is:</strong> Global = <code>docs.z.ai/devpack</code> + <code>api.z.ai</code> + <code>glm_coding_plan_global</code>. China = <code>docs.bigmodel.cn/cn/coding-plan</code> + <code>open.bigmodel.cn</code> + <code>glm_coding_plan_china</code>.</p><p><strong>Why it exists:</strong> Different keys, hosts, and allow-lists.</p><p><strong>What it is not:</strong> Two skins of Z.ai chat.</p>`,40)])])}const b=a(n,[["render",i]]);export{f as __pageData,b as default};
